<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><div class="modal workspace-dialog"><div class="modal-head"><div><h2>Meus workspaces</h2><p>Sua permissão pode mudar em cada ambiente.</p></div><button @click="$emit('close')"><X/></button></div><div class="workspace-list"><button v-for="item in workspaces" :key="item.id" :class="{current:item.id===current}" @click="$emit('select',item.id)"><span><strong>{{item.name}}</strong><small>{{item.role}}</small></span><Check v-if="item.id===current"/></button></div><form v-if="creating" class="new-workspace" @submit.prevent="$emit('create',name)"><input v-model="name" placeholder="Nome do novo workspace" required/><button class="primary-btn"><Plus/>Criar</button></form><button v-else class="new-workspace-btn" @click="creating=true"><Plus/>Criar novo workspace</button><form v-if="currentRole==='OWNER'" class="new-workspace" @submit.prevent="$emit('rename',rename)"><input v-model="rename" placeholder="Nome do workspace atual" required/><button class="primary-btn">Salvar nome</button></form></div></div></template>
<script setup lang="ts">import{ref}from"vue";import{Check,Plus,X}from"lucide-vue-next";import type{WorkspaceRecord,WorkspaceRole}from"../stores/workspaces";const props=defineProps<{workspaces:WorkspaceRecord[];current:string|null;currentRole?:WorkspaceRole}>();defineEmits(["close","select","create","rename"]);const creating=ref(false),name=ref(""),rename=ref(props.workspaces.find(item=>item.id===props.current)?.name||"");</script>
